import heapq


def shortest_path(edges, start, end):
    """
    最短路問題をDijkstraアルゴリズムで解く関数。

    Parameters:
    edges: (from_node, to_node, weight) タプルのリスト
    start: 始点ノード
    end: 終点ノード

    Returns:
    (distance, path) のタプル。負のエッジがある場合はValueErrorを送出。
    経路が存在しない場合は (None, None)。
    start == end の場合は (0, [start])。
    """
    # 負のエッジをチェック
    for u, v, w in edges:
        if w < 0:
            raise ValueError("Negative edge weight found")

    # start と end が同じ場合
    if start == end:
        return (0, [start])

    # アジャセンスリストの構築
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append((v, w))

    # Dijkstraアルゴリズム
    # d[node] = startからの最短距離
    d = {}
    # prev[node] = 最短経路上での前ノード
    prev = {}

    # ユーティリティノードをすべて初期化
    all_nodes = set()
    for u, v, _ in edges:
        all_nodes.add(u)
        all_nodes.add(v)
    all_nodes.add(start)
    all_nodes.add(end)

    for node in all_nodes:
        d[node] = float('inf')
        prev[node] = None

    d[start] = 0

    # ヒープ: (distance, node)
    heap = [(0, start)]
    visited = set()

    while heap:
        dist, u = heapq.heappop(heap)

        # すでに訪問済みならスキップ
        if u in visited:
            continue

        visited.add(u)

        # end に到達したら早期終了
        if u == end:
            break

        # 隣接ノードを探索
        if u in graph:
            for v, w in graph[u]:
                if w < 0:
                    raise ValueError("Negative edge weight found")
                new_dist = dist + w
                if new_dist < d[v]:
                    d[v] = new_dist
                    prev[v] = u
                    heapq.heappush(heap, (new_dist, v))

    # 経路が存在しない場合
    if d[end] == float('inf'):
        return (None, None)

    # 経路を逆方向にトレース
    path = []
    node = end
    while node is not None:
        path.append(node)
        node = prev[node]
    path.reverse()

    return (d[end], path)
